param([string]$BaseUrl='http://localhost:14200')
$ProjectRoot = (Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path
$ErrorActionPreference='Stop';$en=Invoke-RestMethod "$BaseUrl/api/products?lang=en";$zh=Invoke-RestMethod "$BaseUrl/api/products?lang=zh-CN";if($en[0].name-eq$zh[0].name-or$zh[0].name-notmatch'学习'){throw 'Product translation was not selected by locale'}
$keys=docker compose --project-directory $ProjectRoot exec -T commerce-redis redis-cli --scan --pattern 'commerceflow:catalog:products:v1:*';if($keys-notcontains'commerceflow:catalog:products:v1:en'-or$keys-notcontains'commerceflow:catalog:products:v1:zh-CN'){throw 'Locale-isolated cache keys missing'}
$session=[Microsoft.PowerShell.Commands.WebRequestSession]::new();$csrf=Invoke-RestMethod "$BaseUrl/api/auth/csrf" -WebSession $session;$headers=@{$csrf.headerName=$csrf.token};try{Invoke-RestMethod "$BaseUrl/api/auth/login" -Method Post -WebSession $session -Headers $headers -ContentType application/json -Body '{"email":"demo@example.com","password":"wrong-password","rememberMe":false}' -ErrorAction Stop|Out-Null;throw 'Invalid login accepted'}catch{$body=$_.ErrorDetails.Message|ConvertFrom-Json;if($body.code-ne'AUTH_INVALID'){throw "Stable error code missing: $($body.code)"}}
$bundle=(Invoke-WebRequest "$BaseUrl" -UseBasicParsing).Content;if($bundle-notmatch'<app-root'){throw 'Angular application unavailable'}
Write-Host "Chapter 09 verification passed: English/Chinese products, isolated cache, persisted UI bundle, error code AUTH_INVALID" -ForegroundColor Green
